/// Service AI sementara (dummy).
/// Nanti tinggal ganti isi `generateResponse` dengan streaming dari model
/// (misal flutter_litert_lm / flutter_gemma). Interface sudah cocok.
class DummyAiService {
  Stream<String> generateResponse(String prompt) async* {
      final response = _pickResponse(prompt.toLowerCase());
          final words = response.split(' ');
              for (var i = 0; i < words.length; i++) {
                    await Future.delayed(const Duration(milliseconds: 35));
                          yield i == 0 ? words[i] : ' ${words[i]}';
                              }
                                }

                                  String _pickResponse(String prompt) {
                                      if (prompt.contains('halo') ||
                                              prompt.contains('hi') ||
                                                      prompt.contains('hello')) {
                                                            return 'Halo! 👋 Saya asisten AI offline-mu. Saat ini saya berjalan dalam '
                                                                      '**mode demo**, jadi jawaban masih template. Setelah model Qwen atau Gemma '
                                                                                'dipasang di perangkat, saya akan menjawab sepenuhnya offline tanpa internet.';
                                                                                    }
                                                                                        if (prompt.contains('pr') || prompt.contains('matematika')) {
                                                                                              return 'Siap, saya bantu PR-nya! 📚\n\n'
                                                                                                        'Contoh soal: *Jika 3x + 5 = 20, berapa x?*\n\n'
                                                                                                                  '**Penyelesaian:**\n\n'
                                                                                                                            '1. Kurangi kedua sisi dengan 5:\n'
                                                                                                                                      '   `3x = 20 - 5 = 15`\n'
                                                                                                                                                '2. Bagi dengan 3:\n'
                                                                                                                                                          '   `x = 15 / 3 = 5`\n\n'
                                                                                                                                                                    'Jadi, **x = 5** ✅\n\n'
                                                                                                                                                                              '> Di mode demo saya pakai template. Setelah model lokal aktif, '
                                                                                                                                                                                        'jawaban akan dihasilkan langsung di perangkat.';
                                                                                                                                                                                            }
                                                                                                                                                                                                if (prompt.contains('kode') ||
                                                                                                                                                                                                        prompt.contains('code') ||
                                                                                                                                                                                                                prompt.contains('flutter')) {
                                                                                                                                                                                                                      return 'Ini contoh kode Flutter sederhana: 💻\n\n'
                                                                                                                                                                                                                                '```dart\n'
                                                                                                                                                                                                                                          "import 'package:flutter/material.dart';\n\n"
                                                                                                                                                                                                                                                    'void main() => runApp(MyApp());\n\n'
                                                                                                                                                                                                                                                              'class MyApp extends StatelessWidget {\n'
                                                                                                                                                                                                                                                                        '  @override\n'
                                                                                                                                                                                                                                                                                  '  Widget build(BuildContext context) {\n'
                                                                                                                                                                                                                                                                                            '    return MaterialApp(\n'
                                                                                                                                                                                                                                                                                                      '      home: Scaffold(\n'
                                                                                                                                                                                                                                                                                                                "        body: Center(child: Text('Halo, dunia!')),\n"
                                                                                                                                                                                                                                                                                                                          '      ),\n'
                                                                                                                                                                                                                                                                                                                                    '    );\n'
                                                                                                                                                                                                                                                                                                                                              '  }\n'
                                                                                                                                                                                                                                                                                                                                                        '}\n'
                                                                                                                                                                                                                                                                                                                                                                  '```\n\n'
                                                                                                                                                                                                                                                                                                                                                                            'Kode di atas membuat aplikasi Flutter minimal yang menampilkan teks di tengah layar.';
                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                    if (prompt.contains('ngobrol') ||
                                                                                                                                                                                                                                                                                                                                                                                            prompt.contains('curhat') ||
                                                                                                                                                                                                                                                                                                                                                                                                    prompt.contains('santai')) {
                                                                                                                                                                                                                                                                                                                                                                                                          return 'Boleh banget! 😊 Cerita aja — tentang hari kamu, hobi, atau apa pun. '
                                                                                                                                                                                                                                                                                                                                                                                                                    'Meski mode demo, saya akan balas dengan hangat. Setelah model aktif, '
                                                                                                                                                                                                                                                                                                                                                                                                                              'percakapan akan terasa jauh lebih hidup.';
                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                      return 'Kamu bertanya: *"$prompt"*\n\n'
                                                                                                                                                                                                                                                                                                                                                                                                                                              'Mode demo belum bisa memahami konteks penuh. Setelah model AI offline '
                                                                                                                                                                                                                                                                                                                                                                                                                                                      '(Qwen 2.5 atau Gemma 3) dipasang, saya akan menjawab pertanyaan ini '
                                                                                                                                                                                                                                                                                                                                                                                                                                                              'langsung di perangkatmu — tanpa internet sama sekali. 🚀';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }